<script setup lang="ts">import { router, useForm } from '@inertiajs/vue3';import { ref } from 'vue';import { CalendarPlus, Upload } from 'lucide-vue-next';import BusinessLayout from '@/layouts/BusinessLayout.vue';defineProps<{workdays:any;year:number}>();const form=useForm({date:'',is_workday:true,name:''});const save=()=>form.post('/admin/workdays',{onSuccess:()=>form.reset()});const file=ref<File|null>(null);const upload=()=>file.value&&router.post('/admin/workdays/import',{file:file.value},{forceFormData:true});</script><template><BusinessLayout title="工作日历" eyebrow="法定时限依据"><div class="mb-5 border-l-4 border-[#2f6a59] bg-white px-4 py-3 text-sm text-[#42514b]">未单独维护的日期，默认按周一至周五为工作日、周六周日为休息日。此处只需维护法定节假日、调休等例外日期。</div><div class="mb-5 grid gap-5 lg:grid-cols-2"><form class="form-card" @submit.prevent="save"><h2 class="mb-1 font-serif text-lg font-semibold">维护例外日期</h2><p class="mb-4 text-sm text-[#75807b]">手工设置将覆盖默认的周一至周五规则</p><div class="flex flex-wrap items-end gap-3"><label class="field"><span>日期</span><input v-model="form.date" type="date" required></label><label class="field"><span>日期性质</span><select v-model="form.is_workday"><option :value="true">工作日</option><option :value="false">休息日</option></select></label><label class="field flex-1"><span>名称</span><input v-model="form.name" placeholder="节假日或调休说明"></label><button class="btn-primary"><CalendarPlus :size="16"/>保存</button></div></form><div class="form-card"><h2 class="font-serif text-lg font-semibold">批量导入例外日期</h2><p class="mt-1 text-sm text-[#75807b]">CSV/XLSX 列：日期、是否工作日、名称</p><div class="mt-5 flex items-center gap-3"><input type="file" accept=".csv,.xlsx" @change="file=($event.target as HTMLInputElement).files?.[0]||null"><button class="btn-secondary" @click="upload"><Upload :size="16"/>导入</button></div></div></div><div class="table-card"><table><thead><tr><th>例外日期</th><th>性质</th><th>名称</th><th>更新时间</th></tr></thead><tbody><tr v-for="d in workdays.data" :key="d.date"><td>{{d.date}}</td><td><span :class="d.is_workday?'text-emerald-700':'text-amber-700'">{{d.is_workday?'工作日':'休息日'}}</span></td><td>{{d.name||'—'}}</td><td>{{d.updated_at?.slice(0,16)}}</td></tr></tbody></table></div></BusinessLayout></template>
